class ConnectionSettings(object):
    def __init__(self):
        self.__dict__['params'] = {
            'host_ip': '127.0.0.1',
            'ssh_username': 'ute',
            'ssh_password': 'ute',
            'ssh_prompt': '$ ',
            'ssh_port': 22,
            'telnet_port': 20000,
            'telnet_prompt': 'EGATE>',
            'enb_ip': '192.168.255.1',
            'enb_username': 'toor4nsn',
            'enb_password': 'oZPS0POrRieRtu',
            'enb_prompt': ' >',
        }

    def __setattr__(self, key, value):
        if value is not None:
            self.__dict__['params'][key] = value

    def __getattr__(self, item):
        return self.__dict__['params'][item]

    def __getitem__(self, item):
        return self.__dict__['params'][item]

    def __setitem__(self, key, value):
            self.__dict__['params'][key] = value

    @property
    def ssh_connection_params(self):
        """Returns parameters for SSH connection."""
        return {
            'host': self.host_ip,
            'prompt': self.ssh_prompt,
            'timeout': 30,
            'port': self.ssh_port,
        }

    @property
    def ssh_login_params(self):
        """Returns parameters for SSH login operation."""
        return {
            'username': self.ssh_username,
            'password': self.ssh_password
        }

    @property
    def telnet_params(self):
        """Returns parameters for Telnet connection."""
        return {
            'host': self.host_ip,
            'port': self.telnet_port,
            'prompt': self.telnet_prompt
        }

    @property
    def enb_params(self):
        """Returns parameters for eNB SSH connection."""
        return {
            'enb_ip': self.enb_ip,
            'enb_username': self.enb_username,
            'enb_password': self.enb_password,
            'enb_prompt': self.enb_prompt
        }
